1	/**
2	 * Spending Report aggregation (pure)
3	 *
4	 * Rolls a year's Expenses up through the hierarchy
5	 *   Category → Grouping → Area of Importance
6	 * into the month-by-month grid the report renders. No I/O, no dates-from-clock,
7	 * no Supabase — a plain function so it can be unit-tested like the CSV parsers.
8	 *
9	 * Design: docs/plans/2026-07-09-spending-report-design.md
10	 *
11	 * Conventions baked in here (all settled during the grill):
12	 * - Source is Expenses (receipts), bucketed by `transaction_date` (purchase date).
13	 * - Amounts are normalized to the family's currency via the stored FX rate:
14	 *   amount * (exchange_rate_to_cad ?? 1). Refunds are negative and are KEPT
15	 *   negative so they net out (unlike the CSV/PDF exporters, which abs them).
16	 * - Visible month columns run January → the last month that has any expense.
17	 * - A cell with no receipts renders blank; a cell with receipts summing to 0
18	 *   renders 0.00. So each cell carries both an amount and a receipt count.
19	 * - Rows are only emitted where there was activity (zero-activity suppression is
20	 *   automatic — we build rows from the data, not from the full hierarchy).
21	 * - Categories with no Grouping (group_id null / unknown) and receipts with no
22	 *   category land in a bottom "Uncategorized" section, which IS included in the
23	 *   grand total.
24	 */
25	
26	import type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';
27	
28	// Re-export the hierarchy types so callers can import them from here too.
29	export type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';
30	
31	/** The fields of an Expense this aggregation needs. `Expense` satisfies it structurally. */
32	export interface SpendingExpense {
33		total_amount: number | null;
34		transaction_date: string; // 'YYYY-MM-DD'
35		category_id: string | null;
36		exchange_rate_to_cad: number | null;
37	}
38	
39	/** Minimal category shape needed to resolve a receipt to its Grouping. */
40	export interface SpendingCategory {
41		id: string;
42		name: string;
43		group_id?: string | null;
44	}
45	
46	/** One month/YTD cell: the summed amount plus how many receipts contributed. */
47	export interface Cell {
48		amount: number;
49		count: number;
50	}
51	
52	/** A single printed line: a category, a subtotal, or the grand total. */
53	export interface ReportRow {
54		name: string;
55		/** One cell per visible month (parallel to `SpendingReport.months`). */
56		cells: Cell[];
57		/** Year-to-date roll-up across the visible months. */
58		ytd: Cell;
59	}
60	
61	/** A Grouping and its category rows, with the group subtotal. */
62	export interface GroupSection {
63		name: string;
64		rows: ReportRow[];
65		subtotal: ReportRow;
66	}
67	
68	/** An Area of Importance and its groups, with the importance subtotal. */
69	export interface ImportanceSection {
70		name: string;
71		sortOrder: number;
72		groups: GroupSection[];
73		subtotal: ReportRow;
74	}
75	
76	export interface SpendingReport {
77		year: number;
78		/** 1-based month numbers shown as columns, e.g. [1,2,3,4,5,6]. Empty if no data. */
79		months: number[];
80		/** Short labels parallel to `months`, e.g. ['Jan','Feb',...]. */
81		monthLabels: string[];
82		importances: ImportanceSection[];
83		/** Uncategorized spend as its own section; null when everything is categorized. */
84		uncategorized: GroupSection | null;
85		/** Bottom-right roll-up across everything, including Uncategorized. */
86		grandTotal: ReportRow;
87		/** Receipts in `year` with a null amount (counted as $0). Surfaced as a footnote. */
88		missingAmountCount: number;
89	}
90	
91	const MONTH_LABELS = [
92		'Jan',
93		'Feb',
94		'Mar',
95		'Apr',
96		'May',
97		'Jun',
98		'Jul',
99		'Aug',
100		'Sep',
101		'Oct',
102		'Nov',
103		'Dec'
104	];
105	
106	const UNCATEGORIZED_SECTION = 'Uncategorized';
107	const NO_CATEGORY_ROW = '(No category)';
108	
109	/**
110	 * Parse the year and 1-based month out of a 'YYYY-MM-DD' string without
111	 * constructing a Date — bare date strings parse as UTC midnight and can shift a
112	 * day (and thus a month) west of UTC. Returns null for anything unparseable.
113	 */
114	function yearMonth(dateStr: string): { year: number; month: number } | null {
115		if (!dateStr || dateStr.length < 7) return null;
116		const year = Number(dateStr.slice(0, 4));
117		const month = Number(dateStr.slice(5, 7));
118		if (!Number.isInteger(year) || !Number.isInteger(month) || month < 1 || month > 12) {
119			return null;
120		}
121		return { year, month };
122	}
123	
124	/** CAD (family-currency) value of an expense; refunds stay negative. */
125	function normalizedAmount(e: SpendingExpense): number {
126		if (e.total_amount == null) return 0;
127		return e.total_amount * (e.exchange_rate_to_cad ?? 1);
128	}
129	
130	function emptyCells(monthCount: number): Cell[] {
131		return Array.from({ length: monthCount }, () => ({ amount: 0, count: 0 }));
132	}
133	
134	function addInto(target: Cell, amount: number): void {
135		target.amount += amount;
136		target.count += 1;
137	}
138	
139	/** Accumulate one row's cells (and ytd) into another (for subtotals/grand total). */
140	function accumulate(target: ReportRow, source: ReportRow): void {
141		for (let i = 0; i < source.cells.length; i++) {
142			target.cells[i].amount += source.cells[i].amount;
143			target.cells[i].count += source.cells[i].count;
144		}
145		target.ytd.amount += source.ytd.amount;
146		target.ytd.count += source.ytd.count;
147	}
148	
149	function makeRow(name: string, monthCount: number): ReportRow {
150		return { name, cells: emptyCells(monthCount), ytd: { amount: 0, count: 0 } };
151	}
152	
153	/**
154	 * Internal accumulator keyed by group then category, so we can build the tree in
155	 * one pass over the expenses and sort/emit it at the end.
156	 */
157	interface GroupAccumulator {
158		name: string;
159		rows: Map<string, ReportRow>; // category name → row
160	}
161	
162	/**
163	 * Build the spending report grid for a single calendar year.
164	 *
165	 * @param expenses      All expenses (the caller may pass more than `year`; we filter).
166	 * @param categories    Family categories, each carrying its `group_id`.
167	 * @param groups        Family groupings, each carrying its `importance_area_id`.
168	 * @param importanceAreas Family importance areas with `sort_order`.
169	 * @param year          The calendar year to report on.
170	 */
171	export function buildSpendingReport(
172		expenses: SpendingExpense[],
173		categories: SpendingCategory[],
174		groups: CategoryGroup[],
175		importanceAreas: ImportanceArea[],
176		year: number
177	): SpendingReport {
178		// --- lookups -------------------------------------------------------------
179		const categoryById = new Map(categories.map((c) => [c.id, c]));
180		const groupById = new Map(groups.map((g) => [g.id, g]));
181		const importanceById = new Map(importanceAreas.map((a) => [a.id, a]));
182	
183		// --- pass 1: which months are in play, and the missing-amount count --------
184		let maxMonth = 0;
185		let missingAmountCount = 0;
186		const inYear: { e: SpendingExpense; month: number }[] = [];
187		for (const e of expenses) {
188			const ym = yearMonth(e.transaction_date);
189			if (!ym || ym.year !== year) continue;
190			inYear.push({ e, month: ym.month });
191			if (ym.month > maxMonth) maxMonth = ym.month;
192			if (e.total_amount == null) missingAmountCount += 1;
193		}
194	
195		if (maxMonth === 0) {
196			// No expenses this year — empty report (component shows an empty state).
197			return {
198				year,
199				months: [],
200				monthLabels: [],
201				importances: [],
202				uncategorized: null,
203				grandTotal: makeRow('Grand Total', 0),
204				missingAmountCount: 0
205			};
206		}
207	
208		const months = Array.from({ length: maxMonth }, (_, i) => i + 1);
209		const monthLabels = months.map((m) => MONTH_LABELS[m - 1]);
210		const monthCount = months.length;
211		const monthIndex = (m: number) => m - 1; // month 1 → column 0
212	
213		// --- pass 2: bucket each expense into importance → group → category --------
214		// Keyed by importance area id; a synthetic key holds the Uncategorized bucket.
215		const importanceAcc = new Map<string, Map<string, GroupAccumulator>>();
216		const uncategorizedAcc: GroupAccumulator = { name: UNCATEGORIZED_SECTION, rows: new Map() };
217	
218		const ensureRow = (acc: GroupAccumulator, name: string): ReportRow => {
219			let row = acc.rows.get(name);
220			if (!row) {
221				row = makeRow(name, monthCount);
222				acc.rows.set(name, row);
223			}
224			return row;
225		};
226	
227		for (const { e, month } of inYear) {
228			const amount = normalizedAmount(e);
229			const category = e.category_id != null ? categoryById.get(e.category_id) : undefined;
230			const group = category?.group_id != null ? groupById.get(category.group_id) : undefined;
231			const importance = group ? importanceById.get(group.importance_area_id) : undefined;
232	
233			let targetGroupAcc: GroupAccumulator;
234			let rowName: string;
235	
236			if (category && group && importance) {
237				let groupsForImportance = importanceAcc.get(importance.id);
238				if (!groupsForImportance) {
239					groupsForImportance = new Map();
240					importanceAcc.set(importance.id, groupsForImportance);
241				}
242				let groupAcc = groupsForImportance.get(group.id);
243				if (!groupAcc) {
244					groupAcc = { name: group.name, rows: new Map() };
245					groupsForImportance.set(group.id, groupAcc);
246				}
247				targetGroupAcc = groupAcc;
248				rowName = category.name;
249			} else {
250				// Uncategorized: no category, unknown category, category without a group,
251				// or a group/importance that no longer resolves.
252				targetGroupAcc = uncategorizedAcc;
253				rowName = category ? category.name : NO_CATEGORY_ROW;
254			}
255	
256			const row = ensureRow(targetGroupAcc, rowName);
257			addInto(row.cells[monthIndex(month)], amount);
258			addInto(row.ytd, amount);
259		}
260	
261		// --- emit: sort and roll up subtotals -------------------------------------
262		const buildGroupSection = (acc: GroupAccumulator, subtotalName: string): GroupSection => {
263			const rows = [...acc.rows.values()].sort((a, b) => byName(a.name, b.name));
264			const subtotal = makeRow(subtotalName, monthCount);
265			for (const row of rows) accumulate(subtotal, row);
266			return { name: acc.name, rows, subtotal };
267		};
268	
269		const sortedImportances = [...importanceAreas]
270			.filter((a) => importanceAcc.has(a.id))
271			.sort((a, b) => a.sort_order - b.sort_order || byName(a.name, b.name));
272	
273		const importances: ImportanceSection[] = sortedImportances.map((area) => {
274			const groupAccs = importanceAcc.get(area.id)!;
275			const groupSections = [...groupAccs.values()]
276				.map((g) => buildGroupSection(g, `${g.name} Total`))
277				.sort((a, b) => byName(a.name, b.name));
278			const subtotal = makeRow(`${area.name} Total`, monthCount);
279			for (const gs of groupSections) accumulate(subtotal, gs.subtotal);
280			return { name: area.name, sortOrder: area.sort_order, groups: groupSections, subtotal };
281		});
282	
283		const uncategorized =
284			uncategorizedAcc.rows.size > 0
285				? buildGroupSection(uncategorizedAcc, `${UNCATEGORIZED_SECTION} Total`)
286				: null;
287	
288		// --- grand total (includes Uncategorized) ---------------------------------
289		const grandTotal = makeRow('Grand Total', monthCount);
290		for (const imp of importances) accumulate(grandTotal, imp.subtotal);
291		if (uncategorized) accumulate(grandTotal, uncategorized.subtotal);
292	
293		return {
294			year,
295			months,
296			monthLabels,
297			importances,
298			uncategorized,
299			grandTotal,
300			missingAmountCount
301		};
302	}
303	
304	/** Case-insensitive name sort, "(No category)" sinks to the bottom. */
305	function byName(a: string, b: string): number {
306		if (a === NO_CATEGORY_ROW) return 1;
307		if (b === NO_CATEGORY_ROW) return -1;
308		return a.localeCompare(b, undefined, { sensitivity: 'base' });
309	}
310

