/**
 * Shared date-filter glue for the list pages (RF-02).
 *
 * The `expenses`, `receipts`, `transactions` and `reconciliation` pages all drive
 * an identical URL-backed date filter: read+validate `dateFrom`/`dateTo` from the
 * query string, filter an in-memory list against them, and build the query string
 * for the Apply/Clear actions. That glue used to be copy-pasted four times; this
 * module owns the pure logic and each page delegates to it. The reactive `$state`/
 * `$derived`/`$effect`/`goto` wiring stays on the pages (Svelte runes); only the
 * pure computation lives here so it is unit-testable in the node project.
 *
 * Behaviour is pinned by `sharedDateFilter.spec.ts`, whose expectations were
 * validated against the pre-extraction page code via an oracle harness. The two
 * date-math helpers (`toExclusiveEndBoundary`, `defaultMonth*`) are implemented
 * with Y/M/D string/UTC math rather than local `Date`+`toISOString`, which drifts
 * a day at extreme timezones (per CLAUDE.md's date-only-string rule).
 *
 * @module sharedDateFilter
 */

import { getValidDate } from './dateValidation';

export interface DateFilterValues {
	dateFrom: string;
	dateTo: string;
}

const pad = (n: number): string => String(n).padStart(2, '0');

/**
 * Read and validate the `dateFrom`/`dateTo` query parameters. Missing or invalid
 * values (wrong format, impossible dates, injection payloads) become `''`.
 */
export function readDateFilter(searchParams: URLSearchParams): DateFilterValues {
	return {
		dateFrom: getValidDate(searchParams.get('dateFrom')),
		dateTo: getValidDate(searchParams.get('dateTo'))
	};
}

/**
 * Client-side in-memory predicate: does a row's date fall within the range?
 *
 * Rows with no date (`null`/`undefined`/`''`) are always kept — matching the
 * nullable-date pages (expenses/receipts/reconciliation); transactions has a
 * non-null date column, so the same predicate is equivalent for it. Bounds are
 * inclusive and compared as `YYYY-MM-DD` strings (never `new Date`).
 */
export function matchesDateRange(
	date: string | null | undefined,
	dateFrom: string,
	dateTo: string
): boolean {
	if (!date) return true;
	if (dateFrom && date < dateFrom) return false;
	if (dateTo && date > dateTo) return false;
	return true;
}

/**
 * Build the query params for "Apply": set each bound when truthy, delete it when
 * empty, and preserve all other params. Returns a new `URLSearchParams`; the input
 * is not mutated.
 */
export function applyDateFilterParams(
	current: URLSearchParams,
	dateFrom: string,
	dateTo: string
): URLSearchParams {
	const params = new URLSearchParams(current);
	if (dateFrom) params.set('dateFrom', dateFrom);
	else params.delete('dateFrom');
	if (dateTo) params.set('dateTo', dateTo);
	else params.delete('dateTo');
	return params;
}

/**
 * Build the query params for "Clear": drop both date bounds, preserve everything
 * else. Returns a new `URLSearchParams`; the input is not mutated.
 */
export function clearDateFilterParams(current: URLSearchParams): URLSearchParams {
	const params = new URLSearchParams(current);
	params.delete('dateFrom');
	params.delete('dateTo');
	return params;
}

/**
 * Convert an inclusive `dateTo` into the exclusive end boundary a `< beforeDate`
 * query needs: the next calendar day. Uses UTC arithmetic so the result never
 * drifts by a day regardless of the runtime timezone.
 *
 * @example toExclusiveEndBoundary('2025-01-31') // '2025-02-01'
 */
export function toExclusiveEndBoundary(dateTo: string): string {
	const [year, month, day] = dateTo.split('-').map(Number);
	const next = new Date(Date.UTC(year, month - 1, day + 1));
	return `${next.getUTCFullYear()}-${pad(next.getUTCMonth() + 1)}-${pad(next.getUTCDate())}`;
}

/**
 * First day of the reference date's month, as `YYYY-MM-DD`. Used by reconciliation
 * as the default range start when the URL carries no dates. Built from the local
 * calendar parts, so it is timezone-stable.
 */
export function defaultMonthStart(ref: Date): string {
	return `${ref.getFullYear()}-${pad(ref.getMonth() + 1)}-01`;
}

/**
 * Last day of the reference date's month, as `YYYY-MM-DD`. Used by reconciliation
 * as the default range end when the URL carries no dates. Timezone-stable.
 */
export function defaultMonthEnd(ref: Date): string {
	const year = ref.getFullYear();
	const month = ref.getMonth();
	const lastDay = new Date(year, month + 1, 0).getDate();
	return `${year}-${pad(month + 1)}-${pad(lastDay)}`;
}

