//   Essential → Everyday → [Groceries, Dining]
//   Priorities → Kids → [Daycare]
const categories: SpendingCategory[] = [
	{ id: 'cat-groceries', name: 'Groceries', group_id: 'grp-everyday' },
	{ id: 'cat-dining', name: 'Dining', group_id: 'grp-everyday' },
	{ id: 'cat-daycare', name: 'Daycare', group_id: 'grp-kids' },
	{ id: 'cat-orphan', name: 'Orphan', group_id: null }
];

const groups: CategoryGroup[] = [
	{ id: 'grp-everyday', name: 'Everyday', importance_area_id: 'imp-essential' },
	{ id: 'grp-kids', name: 'Kids', importance_area_id: 'imp-priorities' }
];

describe('buildSpendingDrilldownParams', () => {
	it('links a category × month cell to that category and that month', () => {
		const params = buildSpendingDrilldownParams(
			{ kind: 'category', categoryId: 'cat-groceries' },
			{ kind: 'month', month: 3 },
			2026,
			categories,
			groups
		);

		expect(params.get('category')).toBe('cat-groceries');
		expect(params.get('dateFrom')).toBe('2026-03-01');
		expect(params.get('dateTo')).toBe('2026-03-31');
		expect(params.get('filter')).toBeNull();
	});

	it('links a category × Year-to-Date cell to the whole selected year', () => {
		const params = buildSpendingDrilldownParams(
			{ kind: 'category', categoryId: 'cat-groceries' },
			{ kind: 'ytd' },
			2026,
			categories,
			groups
		);

		expect(params.get('category')).toBe('cat-groceries');
		expect(params.get('dateFrom')).toBe('2026-01-01');
		expect(params.get('dateTo')).toBe('2026-12-31');
	});

	it('uses the correct last day for a short month (February, non-leap)', () => {
		const params = buildSpendingDrilldownParams(
			{ kind: 'category', categoryId: 'cat-groceries' },
			{ kind: 'month', month: 2 },
			2027,
			categories,
			groups
		);

		expect(params.get('dateFrom')).toBe('2027-02-01');
		expect(params.get('dateTo')).toBe('2027-02-28');
	});

	it('expands a Grouping subtotal to every category id in that group', () => {
		const params = buildSpendingDrilldownParams(
			{ kind: 'group', groupId: 'grp-everyday' },
			{ kind: 'month', month: 3 },
			2026,
			categories,
			groups
		);

		expect(params.get('category')?.split(',').sort()).toEqual(['cat-dining', 'cat-groceries']);
		expect(params.get('dateFrom')).toBe('2026-03-01');
		expect(params.get('dateTo')).toBe('2026-03-31');
	});

	it('expands an Importance subtotal to every category across its groups', () => {
		// Add a second Essential group so the importance spans more than one group.
		const withSecondGroup: CategoryGroup[] = [
			...groups,
			{ id: 'grp-home', name: 'Home', importance_area_id: 'imp-essential' }
		];
		const withHomeCat: SpendingCategory[] = [
			...categories,
			{ id: 'cat-rent', name: 'Rent', group_id: 'grp-home' }
		];

		const params = buildSpendingDrilldownParams(
			{ kind: 'importance', importanceId: 'imp-essential' },
			{ kind: 'ytd' },
			2026,
			withHomeCat,
			withSecondGroup
		);

		// Everyday (Groceries, Dining) + Home (Rent) — but NOT Priorities' Daycare.
		expect(params.get('category')?.split(',').sort()).toEqual([
			'cat-dining',
			'cat-groceries',
			'cat-rent'
		]);
	});

	it('links an Uncategorized cell via filter=uncategorized, not a category list', () => {
		const params = buildSpendingDrilldownParams(
			{ kind: 'uncategorized' },
			{ kind: 'month', month: 5 },
			2026,
			categories,
			groups
		);

		expect(params.get('filter')).toBe('uncategorized');
		expect(params.get('category')).toBeNull();
		expect(params.get('dateFrom')).toBe('2026-05-01');
		expect(params.get('dateTo')).toBe('2026-05-31');
	});

	it('links the Grand Total to the date range alone (all expenses, incl. Uncategorized)', () => {
		const params = buildSpendingDrilldownParams(
			{ kind: 'grandTotal' },
			{ kind: 'ytd' },
			2026,
			categories,
			groups
		);

		expect(params.get('category')).toBeNull();
		expect(params.get('filter')).toBeNull();
		expect(params.get('dateFrom')).toBe('2026-01-01');
		expect(params.get('dateTo')).toBe('2026-12-31');
	});
});

