/**
 * Spending Report → Expenses drill-down (pure)
 *
 * Turns a clicked report cell into the URL query the Expenses page already
 * understands, so a number in the roll-up jumps to exactly the Expenses that
 * produced it. No I/O — a plain function, unit-tested like `spendingReport`.
 *
 * Design: docs/plans/2026-07-09-spending-report-design.md ("drill from a table
 * cell into the Expenses view").
 *
 * The Expenses page reads (see src/routes/expenses/+page.svelte):
 * - `dateFrom` / `dateTo` — inclusive `YYYY-MM-DD` bounds (via readDateFilter).
 * - `category` — comma-separated category ids (OR filter).
 * - `filter=uncategorized` — show only expenses with no category (takes
 *   precedence over `category`, so the two are never set together).
 */

import type { SpendingCategory } from './spendingReport';
import type { CategoryGroup } from '$lib/types/Hierarchy';

/** What a clicked cell rolls up — the row/section identity. */
export type DrilldownScope =
	| { kind: 'category'; categoryId: string }
	| { kind: 'group'; groupId: string }
	| { kind: 'importance'; importanceId: string }
	| { kind: 'uncategorized' }
	| { kind: 'grandTotal' };

/** Which column was clicked — a single month or the Year-to-Date roll-up. */
export type DrilldownColumn = { kind: 'month'; month: number } | { kind: 'ytd' };

const pad = (n: number): string => String(n).padStart(2, '0');

/** Inclusive `YYYY-MM-DD` bounds for the clicked column within `year`. */
function dateBounds(column: DrilldownColumn, year: number): { from: string; to: string } {
	if (column.kind === 'ytd') {
		return { from: `${year}-01-01`, to: `${year}-12-31` };
	}
	const month = column.month;
	// Numeric Date constructor (not string parsing) is timezone-safe here.
	const lastDay = new Date(year, month, 0).getDate();
	return { from: `${year}-${pad(month)}-01`, to: `${year}-${pad(month)}-${pad(lastDay)}` };
}

/**
 * Build the `/expenses?…` query params for a clicked Spending Report cell.
 *
 * @param scope       What the cell rolls up (category / group / importance / …).
 * @param column      The clicked month, or the Year-to-Date column.
 * @param year        The report's calendar year.
 * @param categories  Family categories (to expand a group/importance to its ids).
 * @param groups      Family groupings (to expand an importance to its groups).
 */
export function buildSpendingDrilldownParams(
	scope: DrilldownScope,
	column: DrilldownColumn,
	year: number,
	categories: SpendingCategory[],
	groups: CategoryGroup[]
): URLSearchParams {
	const params = new URLSearchParams();
	const { from, to } = dateBounds(column, year);
	params.set('dateFrom', from);
	params.set('dateTo', to);

	if (scope.kind === 'uncategorized') {
		params.set('filter', 'uncategorized');
		return params;
	}

	const categoryIds = scopeCategoryIds(scope, categories, groups);
	if (categoryIds) {
		params.set('category', categoryIds.join(','));
	}

	return params;
}

/**
 * The category ids a scope rolls up, or null when the scope carries no category
 * filter (grand total → all expenses; uncategorized → the `filter` param instead).
 */
function scopeCategoryIds(
	scope: DrilldownScope,
	categories: SpendingCategory[],
	groups: CategoryGroup[]
): string[] | null {
	switch (scope.kind) {
		case 'category':
			return [scope.categoryId];
		case 'group':
			return categories.filter((c) => c.group_id === scope.groupId).map((c) => c.id);
		case 'importance': {
			const groupIds = new Set(
				groups.filter((g) => g.importance_area_id === scope.importanceId).map((g) => g.id)
			);
			return categories
				.filter((c) => c.group_id != null && groupIds.has(c.group_id))
				.map((c) => c.id);
		}
		default:
			return null;
	}
}

