1	import { describe, it, expect } from 'vitest';
2	import { buildSpendingReport, type SpendingExpense, type SpendingCategory } from './spendingReport';
3	import type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';
4	
5	// --- fixtures ---------------------------------------------------------------
6	
7	const importanceAreas: ImportanceArea[] = [
8		{ id: 'imp-ess', name: 'Essential', sort_order: 1 },
9		{ id: 'imp-pri', name: 'Priorities', sort_order: 2 },
10		{ id: 'imp-oth', name: 'Other', sort_order: 3 }
11	];
12	
13	const groups: CategoryGroup[] = [
14		{ id: 'grp-everyday', name: 'Everyday', importance_area_id: 'imp-ess' },
15		{ id: 'grp-home', name: 'Home', importance_area_id: 'imp-ess' },
16		{ id: 'grp-kids', name: 'Kids', importance_area_id: 'imp-pri' },
17		{ id: 'grp-disc', name: 'Discretionary', importance_area_id: 'imp-oth' }
18	];
19	
20	const categories: SpendingCategory[] = [
21		{ id: 'cat-groceries', name: 'Groceries', group_id: 'grp-everyday' },
22		{ id: 'cat-clothes', name: 'Clothes', group_id: 'grp-everyday' },
23		{ id: 'cat-utilities', name: 'Utilities', group_id: 'grp-home' },
24		{ id: 'cat-allowance', name: 'Allowance', group_id: 'grp-kids' },
25		{ id: 'cat-alcohol', name: 'Alcohol', group_id: 'grp-disc' },
26		{ id: 'cat-orphan', name: 'Orphan', group_id: null } // no group → Uncategorized
27	];
28	
29	function expense(overrides: Partial<SpendingExpense>): SpendingExpense {
30		return {
31			total_amount: 100,
32			transaction_date: '2026-01-15',
33			category_id: 'cat-groceries',
34			exchange_rate_to_cad: null,
35			...overrides
36		};
37	}
38	
39	function report(expenses: SpendingExpense[], year = 2026) {
40		return buildSpendingReport(expenses, categories, groups, importanceAreas, year);
41	}
42	
43	// Find a category row within an importance/group by name.
44	function findRow(
45		r: ReturnType<typeof report>,
46		importance: string,
47		group: string,
48		category: string
49	) {
50		const imp = r.importances.find((i) => i.name === importance);
51		const grp = imp?.groups.find((g) => g.name === group);
52		return grp?.rows.find((row) => row.name === category);
53	}
54	
55	// --- month columns ----------------------------------------------------------
56	
57	describe('month columns', () => {
58		it('runs January → the last month that has any expense', () => {
59			const r = report([
60				expense({ transaction_date: '2026-01-10' }),
61				expense({ transaction_date: '2026-06-20' })
62			]);
63			expect(r.months).toEqual([1, 2, 3, 4, 5, 6]);
64			expect(r.monthLabels).toEqual(['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun']);
65		});
66	
67		it('ignores expenses from other years when sizing the columns', () => {
68			const r = report([
69				expense({ transaction_date: '2026-03-01' }),
70				expense({ transaction_date: '2025-12-01' }),
71				expense({ transaction_date: '2027-01-01' })
72			]);
73			expect(r.months).toEqual([1, 2, 3]);
74		});
75	
76		it('a null-amount receipt still extends the columns', () => {
77			const r = report([expense({ transaction_date: '2026-05-01', total_amount: null })]);
78			expect(r.months).toEqual([1, 2, 3, 4, 5]);
79		});
80	
81		it('returns an empty report when the year has no expenses', () => {
82			const r = report([expense({ transaction_date: '2025-05-01' })]);
83			expect(r.months).toEqual([]);
84			expect(r.importances).toEqual([]);
85			expect(r.uncategorized).toBeNull();
86			expect(r.grandTotal.ytd.amount).toBe(0);
87		});
88	});
89	
90	// --- roll-up and subtotals --------------------------------------------------
91	
92	describe('roll-up', () => {
93		it('sums a category into the right month column and YTD', () => {
94			const r = report([
95				expense({ category_id: 'cat-groceries', transaction_date: '2026-01-05', total_amount: 40 }),
96				expense({ category_id: 'cat-groceries', transaction_date: '2026-01-25', total_amount: 60 }),
97				expense({ category_id: 'cat-groceries', transaction_date: '2026-02-10', total_amount: 30 })
98			]);
99			const row = findRow(r, 'Essential', 'Everyday', 'Groceries')!;
100			expect(row.cells[0].amount).toBe(100); // Jan
101			expect(row.cells[0].count).toBe(2);
102			expect(row.cells[1].amount).toBe(30); // Feb
103			expect(row.ytd.amount).toBe(130);
104			expect(row.ytd.count).toBe(3);
105		});
106	
107		it('group subtotal sums its categories', () => {
108			const r = report([
109				expense({ category_id: 'cat-groceries', transaction_date: '2026-01-05', total_amount: 40 }),
110				expense({ category_id: 'cat-clothes', transaction_date: '2026-01-06', total_amount: 25 })
111			]);
112			const everyday = r.importances[0].groups.find((g) => g.name === 'Everyday')!;
113			expect(everyday.subtotal.cells[0].amount).toBe(65);
114			expect(everyday.subtotal.ytd.amount).toBe(65);
115		});
116	
117		it('importance subtotal sums its groups', () => {
118			const r = report([
119				expense({ category_id: 'cat-groceries', transaction_date: '2026-01-05', total_amount: 40 }),
120				expense({ category_id: 'cat-utilities', transaction_date: '2026-01-06', total_amount: 200 })
121			]);
122			const essential = r.importances.find((i) => i.name === 'Essential')!;
123			expect(essential.subtotal.ytd.amount).toBe(240);
124		});
125	
126		it('grand total sums every importance', () => {
127			const r = report([
128				expense({ category_id: 'cat-groceries', total_amount: 40 }),
129				expense({ category_id: 'cat-allowance', total_amount: 10 }),
130				expense({ category_id: 'cat-alcohol', total_amount: 25 })
131			]);
132			expect(r.grandTotal.ytd.amount).toBe(75);
133		});
134	});
135	
136	// --- ordering ---------------------------------------------------------------
137	
138	describe('ordering', () => {
139		it('orders importances by sort_order, groups and categories alphabetically', () => {
140			const r = report([
141				expense({ category_id: 'cat-alcohol', total_amount: 1 }), // Other / Discretionary
142				expense({ category_id: 'cat-allowance', total_amount: 1 }), // Priorities / Kids
143				expense({ category_id: 'cat-utilities', total_amount: 1 }), // Essential / Home
144				expense({ category_id: 'cat-groceries', total_amount: 1 }), // Essential / Everyday
145				expense({ category_id: 'cat-clothes', total_amount: 1 }) // Essential / Everyday
146			]);
147			expect(r.importances.map((i) => i.name)).toEqual(['Essential', 'Priorities', 'Other']);
148			expect(r.importances[0].groups.map((g) => g.name)).toEqual(['Everyday', 'Home']);
149			expect(r.importances[0].groups[0].rows.map((row) => row.name)).toEqual([
150				'Clothes',
151				'Groceries'
152			]);
153		});
154	
155		it('omits importances and groups that have no activity', () => {
156			const r = report([expense({ category_id: 'cat-groceries', total_amount: 5 })]);
157			expect(r.importances.map((i) => i.name)).toEqual(['Essential']);
158			expect(r.importances[0].groups.map((g) => g.name)).toEqual(['Everyday']);
159		});
160	});
161	
162	// --- uncategorized ----------------------------------------------------------
163	
164	describe('uncategorized', () => {
165		it('buckets a category with no group', () => {
166			const r = report([expense({ category_id: 'cat-orphan', total_amount: 50 })]);
167			expect(r.uncategorized).not.toBeNull();
168			expect(r.uncategorized!.rows.map((row) => row.name)).toEqual(['Orphan']);
169			expect(r.uncategorized!.subtotal.ytd.amount).toBe(50);
170		});
171	
172		it('buckets a receipt with no category into "(No category)"', () => {
173			const r = report([expense({ category_id: null, total_amount: 50 })]);
174			expect(r.uncategorized!.rows.map((row) => row.name)).toEqual(['(No category)']);
175		});
176	
177		it('buckets a receipt whose category id is unknown', () => {
178			const r = report([expense({ category_id: 'cat-deleted', total_amount: 50 })]);
179			expect(r.uncategorized!.rows.map((row) => row.name)).toEqual(['(No category)']);
180		});
181	
182		it('sorts "(No category)" last within the uncategorized section', () => {
183			const r = report([
184				expense({ category_id: null, total_amount: 1 }),
185				expense({ category_id: 'cat-orphan', total_amount: 1 })
186			]);
187			expect(r.uncategorized!.rows.map((row) => row.name)).toEqual(['Orphan', '(No category)']);
188		});
189	
190		it('includes uncategorized in the grand total', () => {
191			const r = report([
192				expense({ category_id: 'cat-groceries', total_amount: 40 }),
193				expense({ category_id: 'cat-orphan', total_amount: 60 })
194			]);
195			// Importance subtotals only cover the categorized 40...
196			const importanceSum = r.importances.reduce((s, i) => s + i.subtotal.ytd.amount, 0);
197			expect(importanceSum).toBe(40);
198			// ...but the grand total ties out to true total spend.
199			expect(r.grandTotal.ytd.amount).toBe(100);
200		});
201	
202		it('is null when everything is categorized', () => {
203			const r = report([expense({ category_id: 'cat-groceries', total_amount: 40 })]);
204			expect(r.uncategorized).toBeNull();
205		});
206	});
207	
208	// --- refunds, FX, and null amounts ------------------------------------------
209	
210	describe('amounts', () => {
211		it('nets refunds (negative amounts) against spend', () => {
212			const r = report([
213				expense({ category_id: 'cat-groceries', transaction_date: '2026-01-05', total_amount: 100 }),
214				expense({ category_id: 'cat-groceries', transaction_date: '2026-01-06', total_amount: -30 })
215			]);
216			const row = findRow(r, 'Essential', 'Everyday', 'Groceries')!;
217			expect(row.ytd.amount).toBe(70);
218			expect(row.ytd.count).toBe(2); // both receipts counted as activity
219		});
220	
221		it('normalizes foreign currency with the stored FX rate', () => {
222			const r = report([
223				expense({ category_id: 'cat-groceries', total_amount: 100, exchange_rate_to_cad: 1.35 })
