import { describe, it, expect } from 'vitest';
import { buildSpendingReport, type SpendingExpense, type SpendingCategory } from './spendingReport';
import type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';

// --- fixtures ---------------------------------------------------------------

const importanceAreas: ImportanceArea[] = [
	{ id: 'imp-ess', name: 'Essential', sort_order: 1 },
	{ id: 'imp-pri', name: 'Priorities', sort_order: 2 },
	{ id: 'imp-oth', name: 'Other', sort_order: 3 }
];

const groups: CategoryGroup[] = [
	{ id: 'grp-everyday', name: 'Everyday', importance_area_id: 'imp-ess' },
	{ id: 'grp-home', name: 'Home', importance_area_id: 'imp-ess' },
	{ id: 'grp-kids', name: 'Kids', importance_area_id: 'imp-pri' },
	{ id: 'grp-disc', name: 'Discretionary', importance_area_id: 'imp-oth' }
];

const categories: SpendingCategory[] = [
	{ id: 'cat-groceries', name: 'Groceries', group_id: 'grp-everyday' },
	{ id: 'cat-clothes', name: 'Clothes', group_id: 'grp-everyday' },
	{ id: 'cat-utilities', name: 'Utilities', group_id: 'grp-home' },
	{ id: 'cat-allowance', name: 'Allowance', group_id: 'grp-kids' },
	{ id: 'cat-alcohol', name: 'Alcohol', group_id: 'grp-disc' },
	{ id: 'cat-orphan', name: 'Orphan', group_id: null } // no group → Uncategorized
];

function expense(overrides: Partial<SpendingExpense>): SpendingExpense {
	return {
		total_amount: 100,
		transaction_date: '2026-01-15',
		category_id: 'cat-groceries',
		exchange_rate_to_cad: null,
		...overrides
	};
}

function report(expenses: SpendingExpense[], year = 2026) {
	return buildSpendingReport(expenses, categories, groups, importanceAreas, year);
}

// Find a category row within an importance/group by name.
function findRow(
	r: ReturnType<typeof report>,
	importance: string,
	group: string,
	category: string
) {
	const imp = r.importances.find((i) => i.name === importance);
	const grp = imp?.groups.find((g) => g.name === group);
	return grp?.rows.find((row) => row.name === category);
}

// --- month columns ----------------------------------------------------------

describe('month columns', () => {
	it('runs January → the last month that has any expense', () => {
		const r = report([
			expense({ transaction_date: '2026-01-10' }),
			expense({ transaction_date: '2026-06-20' })
		]);
		expect(r.months).toEqual([1, 2, 3, 4, 5, 6]);
		expect(r.monthLabels).toEqual(['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun']);
	});

	it('ignores expenses from other years when sizing the columns', () => {
		const r = report([
			expense({ transaction_date: '2026-03-01' }),
			expense({ transaction_date: '2025-12-01' }),
			expense({ transaction_date: '2027-01-01' })
		]);
		expect(r.months).toEqual([1, 2, 3]);
	});

	it('a null-amount receipt still extends the columns', () => {
		const r = report([expense({ transaction_date: '2026-05-01', total_amount: null })]);
		expect(r.months).toEqual([1, 2, 3, 4, 5]);
	});

	it('returns an empty report when the year has no expenses', () => {
		const r = report([expense({ transaction_date: '2025-05-01' })]);
		expect(r.months).toEqual([]);
		expect(r.importances).toEqual([]);
		expect(r.uncategorized).toBeNull();
		expect(r.grandTotal.ytd.amount).toBe(0);
	});
});

// --- roll-up and subtotals --------------------------------------------------

describe('roll-up', () => {
	it('sums a category into the right month column and YTD', () => {
		const r = report([
			expense({ category_id: 'cat-groceries', transaction_date: '2026-01-05', total_amount: 40 }),
			expense({ category_id: 'cat-groceries', transaction_date: '2026-01-25', total_amount: 60 }),
			expense({ category_id: 'cat-groceries', transaction_date: '2026-02-10', total_amount: 30 })
		]);
		const row = findRow(r, 'Essential', 'Everyday', 'Groceries')!;
		expect(row.cells[0].amount).toBe(100); // Jan
		expect(row.cells[0].count).toBe(2);
		expect(row.cells[1].amount).toBe(30); // Feb
		expect(row.ytd.amount).toBe(130);
		expect(row.ytd.count).toBe(3);
	});

	it('group subtotal sums its categories', () => {
		const r = report([
			expense({ category_id: 'cat-groceries', transaction_date: '2026-01-05', total_amount: 40 }),
			expense({ category_id: 'cat-clothes', transaction_date: '2026-01-06', total_amount: 25 })
		]);
		const everyday = r.importances[0].groups.find((g) => g.name === 'Everyday')!;
		expect(everyday.subtotal.cells[0].amount).toBe(65);
		expect(everyday.subtotal.ytd.amount).toBe(65);
	});

	it('importance subtotal sums its groups', () => {
		const r = report([
			expense({ category_id: 'cat-groceries', transaction_date: '2026-01-05', total_amount: 40 }),
			expense({ category_id: 'cat-utilities', transaction_date: '2026-01-06', total_amount: 200 })
		]);
		const essential = r.importances.find((i) => i.name === 'Essential')!;
		expect(essential.subtotal.ytd.amount).toBe(240);
	});

	it('grand total sums every importance', () => {
		const r = report([
			expense({ category_id: 'cat-groceries', total_amount: 40 }),
			expense({ category_id: 'cat-allowance', total_amount: 10 }),
			expense({ category_id: 'cat-alcohol', total_amount: 25 })
		]);
		expect(r.grandTotal.ytd.amount).toBe(75);
	});
});

// --- ordering ---------------------------------------------------------------

describe('ordering', () => {
	it('orders importances by sort_order, groups and categories alphabetically', () => {
		const r = report([
			expense({ category_id: 'cat-alcohol', total_amount: 1 }), // Other / Discretionary
			expense({ category_id: 'cat-allowance', total_amount: 1 }), // Priorities / Kids
			expense({ category_id: 'cat-utilities', total_amount: 1 }), // Essential / Home
			expense({ category_id: 'cat-groceries', total_amount: 1 }), // Essential / Everyday
			expense({ category_id: 'cat-clothes', total_amount: 1 }) // Essential / Everyday
		]);
		expect(r.importances.map((i) => i.name)).toEqual(['Essential', 'Priorities', 'Other']);
		expect(r.importances[0].groups.map((g) => g.name)).toEqual(['Everyday', 'Home']);
		expect(r.importances[0].groups[0].rows.map((row) => row.name)).toEqual([
			'Clothes',
			'Groceries'
		]);
	});

	it('omits importances and groups that have no activity', () => {
		const r = report([expense({ category_id: 'cat-groceries', total_amount: 5 })]);
		expect(r.importances.map((i) => i.name)).toEqual(['Essential']);
		expect(r.importances[0].groups.map((g) => g.name)).toEqual(['Everyday']);
	});
});

// --- uncategorized ----------------------------------------------------------

describe('uncategorized', () => {
	it('buckets a category with no group', () => {
		const r = report([expense({ category_id: 'cat-orphan', total_amount: 50 })]);
		expect(r.uncategorized).not.toBeNull();
		expect(r.uncategorized!.rows.map((row) => row.name)).toEqual(['Orphan']);
		expect(r.uncategorized!.subtotal.ytd.amount).toBe(50);
	});

	it('buckets a receipt with no category into "(No category)"', () => {
		const r = report([expense({ category_id: null, total_amount: 50 })]);
		expect(r.uncategorized!.rows.map((row) => row.name)).toEqual(['(No category)']);
	});

	it('buckets a receipt whose category id is unknown', () => {
		const r = report([expense({ category_id: 'cat-deleted', total_amount: 50 })]);
		expect(r.uncategorized!.rows.map((row) => row.name)).toEqual(['(No category)']);
	});

	it('sorts "(No category)" last within the uncategorized section', () => {
		const r = report([
			expense({ category_id: null, total_amount: 1 }),
			expense({ category_id: 'cat-orphan', total_amount: 1 })
		]);
		expect(r.uncategorized!.rows.map((row) => row.name)).toEqual(['Orphan', '(No category)']);
	});

	it('includes uncategorized in the grand total', () => {
		const r = report([
			expense({ category_id: 'cat-groceries', total_amount: 40 }),
			expense({ category_id: 'cat-orphan', total_amount: 60 })
		]);
		// Importance subtotals only cover the categorized 40...
		const importanceSum = r.importances.reduce((s, i) => s + i.subtotal.ytd.amount, 0);
		expect(importanceSum).toBe(40);
		// ...but the grand total ties out to true total spend.
		expect(r.grandTotal.ytd.amount).toBe(100);
	});

	it('is null when everything is categorized', () => {
		const r = report([expense({ category_id: 'cat-groceries', total_amount: 40 })]);
		expect(r.uncategorized).toBeNull();
	});
});

// --- refunds, FX, and null amounts ------------------------------------------

describe('amounts', () => {
	it('nets refunds (negative amounts) against spend', () => {
		const r = report([
			expense({ category_id: 'cat-groceries', transaction_date: '2026-01-05', total_amount: 100 }),
			expense({ category_id: 'cat-groceries', transaction_date: '2026-01-06', total_amount: -30 })
		]);
		const row = findRow(r, 'Essential', 'Everyday', 'Groceries')!;
		expect(row.ytd.amount).toBe(70);
		expect(row.ytd.count).toBe(2); // both receipts counted as activity
	});

	it('normalizes foreign currency with the stored FX rate', () => {
		const r = report([
			expense({ category_id: 'cat-groceries', total_amount: 100, exchange_rate_to_cad: 1.35 })
		]);
		const row = findRow(r, 'Essential', 'Everyday', 'Groceries')!;
		expect(row.ytd.amount).toBeCloseTo(135);
	});

	it('treats a null amount as 0 but still counts the receipt and flags it', () => {
		const r = report([
			expense({ category_id: 'cat-groceries', transaction_date: '2026-01-05', total_amount: null })
		]);
		const row = findRow(r, 'Essential', 'Everyday', 'Groceries')!;
		expect(row.cells[0].amount).toBe(0);
		expect(row.cells[0].count).toBe(1);
		expect(r.missingAmountCount).toBe(1);
	});
});

// --- blank vs zero cells ----------------------------------------------------

describe('cell activity', () => {
	it('marks months with no receipts as count 0 (rendered blank) and active months with a count', () => {
		const r = report([
			expense({ category_id: 'cat-groceries', transaction_date: '2026-01-05', total_amount: 40 }),
			expense({ category_id: 'cat-groceries', transaction_date: '2026-03-05', total_amount: 40 })
		]);
		const row = findRow(r, 'Essential', 'Everyday', 'Groceries')!;
		expect(row.cells.map((c) => c.count)).toEqual([1, 0, 1]); // Jan active, Feb blank, Mar active
	});

	it('a net-zero month still has a positive count (renders 0.00, not blank)', () => {
		const r = report([
			expense({ category_id: 'cat-groceries', transaction_date: '2026-02-05', total_amount: 50 }),
			expense({ category_id: 'cat-groceries', transaction_date: '2026-02-06', total_amount: -50 })
		]);
		const row = findRow(r, 'Essential', 'Everyday', 'Groceries')!;
		expect(row.cells[1].amount).toBe(0);
		expect(row.cells[1].count).toBe(2);
	});
});

