	it('tags a category detail row with its category id', () => {
		const r = report([expense({ category_id: 'cat-groceries', total_amount: 40 })]);
		const row = findRow(r, 'Essential', 'Everyday', 'Groceries')!;
		expect(row.categoryId).toBe('cat-groceries');
