1	<script lang="ts">
2		/**
3		 * Spending Report page
4		 *
5		 * Rolls a year's Expenses up through Category → Grouping → Area of Importance
6		 * and renders the month-by-month grid (subtotals per Grouping and Importance,
7		 * a Year-to-Date column, Uncategorized at the bottom, Grand Total).
8		 *
9		 * All aggregation is the pure `buildSpendingReport` — this page only loads the
10		 * data and paints the grid. Design: docs/plans/2026-07-09-spending-report-design.md
11		 */
12	
13		import { onMount } from 'svelte';
14		import { supabase } from '$lib/supabaseClient';
15		import { ExpenseService } from '$lib/services/ExpenseService';
16		import { CategoryService } from '$lib/services/CategoryService';
17		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
18		import { formatCurrency } from '$lib/utils/formatCurrency';
19		import {
20			buildSpendingReport,
21			type SpendingReport,
22			type Cell,
23			type ReportRow
24		} from '$lib/utils/spendingReport';
25		import SpendingChart from '$lib/components/SpendingChart.svelte';
26		import type { Session } from '@supabase/supabase-js';
27	
28		let session: Session | null = $state(null);
29		let familyId: string | null = $state(null);
30		let year = $state(new Date().getFullYear());
31		let view = $state<'table' | 'chart'>('table');
32		let loading = $state(true);
33		let error: string | null = $state(null);
34		let report = $state<SpendingReport | null>(null);
35	
36		onMount(async () => {
37			const { data } = await supabase.auth.getSession();
38			session = data.session;
39			if (!session) return;
40	
41			familyId = await getDefaultFamilyId();
42			if (!familyId) {
43				error = 'No family found. Please contact support.';
44				loading = false;
45				return;
46			}
47	
48			await loadReport();
49		});
50	
51		async function loadReport() {
52			if (!session?.user || !familyId) return;
53	
54			try {
55				loading = true;
56				error = null;
57	
58				const categoryService = new CategoryService(supabase);
59				const expenseService = new ExpenseService(supabase);
60	
61				// Seed the default hierarchy the first time a family opens the report
62				// (idempotent server-side), mirroring how categories self-initialize.
63				let importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
64				if (importanceAreas.length === 0) {
65					await categoryService.createDefaultHierarchy(familyId);
66					importanceAreas = await categoryService.getFamilyImportanceAreas(familyId);
67				}
68	
69				const [groups, categories, expenses] = await Promise.all([
70					categoryService.getFamilyGroups(familyId),
71					categoryService.getFamilyCategories(familyId),
72					expenseService.getExpenses(session.user.id, {
73						startDate: `${year}-01-01`,
74						endDate: `${year}-12-31`
75					})
76				]);
77	
78				report = buildSpendingReport(expenses, categories, groups, importanceAreas, year);
79			} catch (err) {
80				console.error('Error loading spending report:', err);
81				error = err instanceof Error ? err.message : 'Failed to load the spending report';
82			} finally {
83				loading = false;
84			}
85		}
86	
87		function changeYear(delta: number) {
88			year += delta;
89			loadReport();
90		}
91	
92		/** A cell renders blank when no receipts fell in it, otherwise the amount. */
93		function cellText(cell: Cell): string {
94			return cell.count === 0 ? '' : formatCurrency(cell.amount);
95		}
96	
97		const hasData = $derived(report !== null && report.months.length > 0);
98	</script>
99	
100	<svelte:head>
101		<title>Spending — YFL Expense Tracker</title>
102	</svelte:head>
103	
104	<div class="spending-page">
105		<div class="mb-6 flex flex-wrap items-center justify-between gap-3">
106			<div>
107				<h1 class="mb-2 text-2xl font-bold">Spending</h1>
108				<p class="text-gray-600">
109					Your expenses by Area of Importance, Grouping, and Category. Amounts in CAD.
110				</p>
111			</div>
112			<div class="flex items-center gap-4">
113				<div class="inline-flex overflow-hidden rounded border border-gray-300" role="group">
114					<button
115						type="button"
116						class="px-3 py-1 text-sm {view === 'table'
117							? 'bg-indigo-600 text-white'
118							: 'bg-white text-gray-700 hover:bg-gray-100'}"
119						aria-pressed={view === 'table'}
120						onclick={() => (view = 'table')}
121					>
122						Table
123					</button>
124					<button
125						type="button"
126						class="border-l border-gray-300 px-3 py-1 text-sm {view === 'chart'
127							? 'bg-indigo-600 text-white'
128							: 'bg-white text-gray-700 hover:bg-gray-100'}"
129						aria-pressed={view === 'chart'}
130						onclick={() => (view = 'chart')}
131					>
132						Chart
133					</button>
134				</div>
135				<div class="flex items-center gap-2">
136					<button
137						type="button"
138						class="rounded border border-gray-300 px-3 py-1 text-sm hover:bg-gray-100"
139						onclick={() => changeYear(-1)}
140						aria-label="Previous year"
141					>
142						←
143					</button>
144					<span class="min-w-16 text-center text-lg font-semibold" aria-live="polite">{year}</span>
145					<button
146						type="button"
147						class="rounded border border-gray-300 px-3 py-1 text-sm hover:bg-gray-100"
148						onclick={() => changeYear(1)}
149						aria-label="Next year"
150					>
151						→
152					</button>
153				</div>
154			</div>
155		</div>
156	
157		{#if loading}
158			<div class="flex items-center justify-center p-8 text-gray-500">Loading spending report…</div>
159		{:else if error}
160			<div class="rounded border border-red-200 bg-red-50 p-4 text-red-700">{error}</div>
161		{:else if !hasData}
162			<div class="rounded border border-gray-200 bg-gray-50 p-8 text-center text-gray-500">
163				No expenses recorded for {year}.
164			</div>
165		{:else if report}
166			{#if report.missingAmountCount > 0}
167				<p class="mb-3 text-sm text-yellow-700">
168					⚠ {report.missingAmountCount} receipt{report.missingAmountCount === 1 ? '' : 's'} in {year}
169					{report.missingAmountCount === 1 ? 'has' : 'have'} no amount and count as $0. Open them on the
170					Receipts page to fix.
171				</p>
172			{/if}
173	
174			{#snippet nameCell(name: string)}
175				<!-- Long category names truncate to one line; the full name shows on hover. -->
176				<span class="block max-w-64 truncate" title={name}>{name}</span>
177			{/snippet}
178	
179			{#snippet valueCells(row: ReportRow)}
180				{#each row.cells as cell (cell)}
181					<td class="px-3 py-1 text-right tabular-nums">{cellText(cell)}</td>
182				{/each}
183				<td class="px-3 py-1 text-right font-semibold tabular-nums">{cellText(row.ytd)}</td>
184			{/snippet}
185	
186			{#if view === 'table'}
187				<div class="overflow-x-auto">
188					<table class="min-w-full border-collapse text-sm">
189						<thead>
190							<tr class="border-b-2 border-gray-300 bg-gray-50 text-gray-700">
191								<th class="px-3 py-2 text-left font-semibold">Category</th>
192								{#each report.monthLabels as label (label)}
193									<th class="px-3 py-2 text-right font-semibold">{label}</th>
194								{/each}
195								<th class="px-3 py-2 text-right font-semibold">Year to Date</th>
196							</tr>
197						</thead>
198						<tbody>
199							{#each report.importances as importance (importance.name)}
200								<tr class="bg-indigo-100 font-semibold text-indigo-900">
201									<td class="px-3 py-1" colspan={report.months.length + 2}>{importance.name}</td>
202								</tr>
203								{#each importance.groups as group (group.name)}
204									{#each group.rows as row (row.name)}
205										<tr class="border-b border-gray-100">
206											<td class="px-3 py-1 pl-8">{@render nameCell(row.name)}</td>
207											{@render valueCells(row)}
208										</tr>
209									{/each}
210									<tr class="border-b border-gray-200 bg-gray-100 font-medium">
211										<td class="px-3 py-1 pl-6">{group.name} Total</td>
212										{@render valueCells(group.subtotal)}
213									</tr>
214								{/each}
215								<tr class="border-b-2 border-indigo-200 bg-indigo-50 font-semibold">
216									<td class="px-3 py-1">{importance.name} Total</td>
217									{@render valueCells(importance.subtotal)}
218								</tr>
219							{/each}
220	
221							{#if report.uncategorized}
222								<tr class="bg-amber-100 font-semibold text-amber-900">
223									<td class="px-3 py-1" colspan={report.months.length + 2}>Uncategorized</td>
224								</tr>
225								{#each report.uncategorized.rows as row (row.name)}
226									<tr class="border-b border-gray-100">
227										<td class="px-3 py-1 pl-8">{@render nameCell(row.name)}</td>
228										{@render valueCells(row)}
229									</tr>
230								{/each}
231								<tr class="border-b-2 border-amber-200 bg-amber-50 font-semibold">
232									<td class="px-3 py-1">Uncategorized Total</td>
233									{@render valueCells(report.uncategorized.subtotal)}
234								</tr>
235							{/if}
236	
237							<tr class="border-t-2 border-gray-400 bg-gray-200 font-bold">
238								<td class="px-3 py-2">Grand Total</td>
239								{@render valueCells(report.grandTotal)}
240							</tr>
241						</tbody>
242					</table>
243				</div>
244			{:else}
245				<SpendingChart {report} />
246			{/if}
247		{/if}
248	</div>
