function cellText(cell: Cell): string {
	return cell.count === 0 ? '' : formatCurrency(cell.amount);
}

/**
 * The drill-down scope for a detail row: a real category when the row maps to
 * one (including a named-but-ungrouped Uncategorized row), otherwise the
 * "(No category)" catch-all drills to the uncategorized Expenses filter.
 */
function rowScope(row: ReportRow): DrilldownScope {
	return row.categoryId
		? { kind: 'category', categoryId: row.categoryId }
		: { kind: 'uncategorized' };
}

/** Link a clicked cell to the Expenses view, filtered to exactly what it sums. */
function cellHref(scope: DrilldownScope, column: DrilldownColumn): string {
	const params = buildSpendingDrilldownParams(scope, column, year, categories, groups);
	return resolve(`/expenses?${params.toString()}`);
}

