1	/**
2	 * Spending Report aggregation (pure)
3	 *
4	 * Rolls a year's Expenses up through the hierarchy
5	 *   Category → Grouping → Area of Importance
6	 * into the month-by-month grid the report renders. No I/O, no dates-from-clock,
7	 * no Supabase — a plain function so it can be unit-tested like the CSV parsers.
8	 *
9	 * Design: docs/plans/2026-07-09-spending-report-design.md
10	 *
11	 * Conventions baked in here (all settled during the grill):
12	 * - Source is Expenses (receipts), bucketed by `transaction_date` (purchase date).
13	 * - Amounts are normalized to the family's currency via the stored FX rate:
14	 *   amount * (exchange_rate_to_cad ?? 1). Refunds are negative and are KEPT
15	 *   negative so they net out (unlike the CSV/PDF exporters, which abs them).
16	 * - Visible month columns run January → the last month that has any expense.
17	 * - A cell with no receipts renders blank; a cell with receipts summing to 0
18	 *   renders 0.00. So each cell carries both an amount and a receipt count.
19	 * - Rows are only emitted where there was activity (zero-activity suppression is
20	 *   automatic — we build rows from the data, not from the full hierarchy).
21	 * - Categories with no Grouping (group_id null / unknown) and receipts with no
22	 *   category land in a bottom "Uncategorized" section, which IS included in the
23	 *   grand total.
24	 */
25	
26	import type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';
27	
28	// Re-export the hierarchy types so callers can import them from here too.
29	export type { ImportanceArea, CategoryGroup } from '$lib/types/Hierarchy';
30	
31	/** The fields of an Expense this aggregation needs. `Expense` satisfies it structurally. */
32	export interface SpendingExpense {
33		total_amount: number | null;
34		transaction_date: string; // 'YYYY-MM-DD'
35		category_id: string | null;
36		exchange_rate_to_cad: number | null;
37	}
38	
39	/** Minimal category shape needed to resolve a receipt to its Grouping. */
40	export interface SpendingCategory {
41		id: string;
42		name: string;
43		group_id?: string | null;
44	}
45	
46	/** One month/YTD cell: the summed amount plus how many receipts contributed. */
47	export interface Cell {
48		amount: number;
49		count: number;
50	}
51	
52	/** A single printed line: a category, a subtotal, or the grand total. */
53	export interface ReportRow {
54		name: string;
55		/**
56		 * The category this row maps to 1:1, for drill-down into the Expenses view.
57		 * Set on category detail rows (including a named-but-ungrouped Uncategorized
58		 * row); undefined on the "(No category)" row and on all subtotal/grand-total
59		 * rows. See `spendingDrilldown.ts`.
60		 */
61		categoryId?: string;
62		/** One cell per visible month (parallel to `SpendingReport.months`). */
63		cells: Cell[];
64		/** Year-to-date roll-up across the visible months. */
65		ytd: Cell;
66	}
67	
68	/** A Grouping and its category rows, with the group subtotal. */
69	export interface GroupSection {
70		name: string;
71		/** The Grouping's id, for drill-down; undefined for the synthetic Uncategorized section. */
72		id?: string;
73		rows: ReportRow[];
74		subtotal: ReportRow;
75	}
76	
77	/** An Area of Importance and its groups, with the importance subtotal. */
78	export interface ImportanceSection {
79		name: string;
80		/** The Area of Importance's id, for drill-down. */
81		id: string;
82		sortOrder: number;
83		groups: GroupSection[];
84		subtotal: ReportRow;
85	}
86	
87	export interface SpendingReport {
88		year: number;
89		/** 1-based month numbers shown as columns, e.g. [1,2,3,4,5,6]. Empty if no data. */
90		months: number[];
91		/** Short labels parallel to `months`, e.g. ['Jan','Feb',...]. */
92		monthLabels: string[];
93		importances: ImportanceSection[];
94		/** Uncategorized spend as its own section; null when everything is categorized. */
95		uncategorized: GroupSection | null;
96		/** Bottom-right roll-up across everything, including Uncategorized. */
97		grandTotal: ReportRow;
98		/** Receipts in `year` with a null amount (counted as $0). Surfaced as a footnote. */
99		missingAmountCount: number;
100	}
101	
102	const MONTH_LABELS = [
103		'Jan',
104		'Feb',
105		'Mar',
106		'Apr',
107		'May',
108		'Jun',
109		'Jul',
110		'Aug',
111		'Sep',
112		'Oct',
113		'Nov',
114		'Dec'
115	];
116	
117	const UNCATEGORIZED_SECTION = 'Uncategorized';
118	const NO_CATEGORY_ROW = '(No category)';
119	
120	/**
121	 * Parse the year and 1-based month out of a 'YYYY-MM-DD' string without
122	 * constructing a Date — bare date strings parse as UTC midnight and can shift a
123	 * day (and thus a month) west of UTC. Returns null for anything unparseable.
124	 */
125	function yearMonth(dateStr: string): { year: number; month: number } | null {
126		if (!dateStr || dateStr.length < 7) return null;
127		const year = Number(dateStr.slice(0, 4));
128		const month = Number(dateStr.slice(5, 7));
129		if (!Number.isInteger(year) || !Number.isInteger(month) || month < 1 || month > 12) {
130			return null;
131		}
132		return { year, month };
133	}
134	
135	/** CAD (family-currency) value of an expense; refunds stay negative. */
136	function normalizedAmount(e: SpendingExpense): number {
137		if (e.total_amount == null) return 0;
138		return e.total_amount * (e.exchange_rate_to_cad ?? 1);
139	}
140	
141	function emptyCells(monthCount: number): Cell[] {
142		return Array.from({ length: monthCount }, () => ({ amount: 0, count: 0 }));
143	}
144	
145	function addInto(target: Cell, amount: number): void {
146		target.amount += amount;
147		target.count += 1;
148	}
149	
150	/** Accumulate one row's cells (and ytd) into another (for subtotals/grand total). */
151	function accumulate(target: ReportRow, source: ReportRow): void {
152		for (let i = 0; i < source.cells.length; i++) {
153			target.cells[i].amount += source.cells[i].amount;
154			target.cells[i].count += source.cells[i].count;
155		}
156		target.ytd.amount += source.ytd.amount;
157		target.ytd.count += source.ytd.count;
158	}
159	
160	function makeRow(name: string, monthCount: number, categoryId?: string): ReportRow {
161		return { name, categoryId, cells: emptyCells(monthCount), ytd: { amount: 0, count: 0 } };
162	}
163	
164	/**
165	 * Internal accumulator keyed by group then category, so we can build the tree in
166	 * one pass over the expenses and sort/emit it at the end.
167	 */
168	interface GroupAccumulator {
169		name: string;
170		/** The Grouping's id; undefined for the synthetic Uncategorized bucket. */
171		id?: string;
172		rows: Map<string, ReportRow>; // category name → row
173	}
174	
175	/**
176	 * Build the spending report grid for a single calendar year.
177	 *
178	 * @param expenses      All expenses (the caller may pass more than `year`; we filter).
179	 * @param categories    Family categories, each carrying its `group_id`.
