file.content:
{#if loading}
	<div class="flex items-center justify-center p-8 text-gray-500">Loading spending report…</div>
{:else if error}
	<div class="rounded border border-red-200 bg-red-50 p-4 text-red-700">{error}</div>
{:else if !hasData}
	<div class="rounded border border-gray-200 bg-gray-50 p-8 text-center text-gray-500">
		No expenses recorded for {year}.
	</div>
{:else if report}
	{#if report.missingAmountCount > 0}
		<p class="mb-3 text-sm text-yellow-700">
			⚠ {report.missingAmountCount} receipt{report.missingAmountCount === 1 ? '' : 's'} in {year}
			{report.missingAmountCount === 1 ? 'has' : 'have'} no amount and count as $0. Open them on the
			Receipts page to fix.
		</p>
	{/if}

	{#snippet nameCell(name: string)}
		<!-- Long category names truncate to one line; the full name shows on hover. -->
		<span class="block max-w-64 truncate" title={name}>{name}</span>
	{/snippet}

	{#snippet valueCells(row: ReportRow, scope: DrilldownScope)}
		{#each row.cells as cell, i (cell)}
			<td class="px-3 py-1 text-right tabular-nums">
				{#if cell.count > 0}
					<!-- months run Jan → maxMonth contiguously, so column i is month i+1 -->
					<a
						class="hover:text-indigo-600 hover:underline"
						href={resolve(`/expenses?${drilldownQuery(scope, { kind: 'month', month: i + 1 })}`)}
						title="View these expenses">{cellText(cell)}</a
					>
				{/if}
			</td>
		{/each}
		<td class="px-3 py-1 text-right font-semibold tabular-nums">
			{#if row.ytd.count > 0}
				<a
					class="hover:text-indigo-600 hover:underline"
					href={resolve(`/expenses?${drilldownQuery(scope, { kind: 'ytd' })}`)}
					title="View these expenses">{cellText(row.ytd)}</a
				>
			{/if}
		</td>
	{/snippet}

	{#if view === 'table'}
		<div class="overflow-x-auto">
			<table class="min-w-full border-collapse text-sm">
				<thead>
					<tr class="border-b-2 border-gray-300 bg-gray-50 text-gray-700">
						<th class="px-3 py-2 text-left font-semibold">Category</th>
						{#each report.monthLabels as label (label)}
							<th class="px-3 py-2 text-right font-semibold">{label}</th>
						{/each}
						<th class="px-3 py-2 text-right font-semibold">Year to Date</th>
					</tr>
				</thead>
				<tbody>
					{#each report.importances as importance (importance.name)}
						<tr class="bg-indigo-100 font-semibold text-indigo-900">
							<td class="px-3 py-1" colspan={report.months.length + 2}>{importance.name}</td>
						</tr>
						{#each importance.groups as group (group.name)}
							{#each group.rows as row (row.name)}
								<tr class="border-b border-gray-100">
									<td class="px-3 py-1 pl-8">{@render nameCell(row.name)}</td>
									{@render valueCells(row, rowScope(row))}
								</tr>
							{/each}
							<tr class="border-b border-gray-200 bg-gray-100 font-medium">
								<td class="px-3 py-1 pl-6">{group.name} Total</td>
								{@render valueCells(group.subtotal, {
									kind: 'group',
									groupId: group.id ?? ''
								})}
							</tr>
						{/each}
						<tr class="border-b-2 border-indigo-200 bg-indigo-50 font-semibold">
